CREATE FUNCTION public.pend_remove_file(_token text,_item uuid,_file uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.pend_itens; path text; BEGIN SELECT i.* INTO r FROM public.pend_itens i JOIN public.pend_links l ON l.id=i.link_id WHERE i.id=_item AND l.token=_token AND l.ativo AND (l.expira_em IS NULL OR l.expira_em>now()) FOR UPDATE OF i; IF r.id IS NULL THEN RAISE EXCEPTION 'Link inválido ou expirado'; END IF; IF r.status='resolvida' THEN RAISE EXCEPTION 'Item resolvido: somente leitura'; END IF; DELETE FROM public.pend_arquivos WHERE id=_file AND item_id=_item RETURNING storage_path INTO path; IF path IS NULL THEN RAISE EXCEPTION 'Arquivo não encontrado'; END IF; RETURN path; END; $$; REVOKE ALL ON FUNCTION public.pend_remove_file(text,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pend_remove_file(text,uuid,uuid) TO service_role;